const Definicion* buscar(const std::string& clave) {
    for (const Definicion& d : registro())
        if (clave == d.clave) return &d;
    return nullptr;
}

std::string validar(const std::string& clave, const json& valor) {
    const Definicion* d = buscar(clave);
    if (d == nullptr) return ba::i18n::traducir("ajustes", "no existe");
    const std::string tipo = d->tipo;
    if (tipo == "bool") return valor.is_boolean() ? std::string() : ba::i18n::traducir("ajustes", "tiene que ser sí o no");
    if (tipo == "int" || tipo == "float") {
        if (!valor.is_number()) return ba::i18n::traducir("ajustes", "tiene que ser un número");
        const double v = valor.get<double>();
        if (tipo == "int" && v != std::floor(v)) return ba::i18n::traducir("ajustes", "tiene que ser un entero");
        if (d->max > d->min && (v < d->min || v > d->max)) return ba::i18n::traducir("ajustes", "fuera de rango");
        return {};
    }
    if (!valor.is_string()) return ba::i18n::traducir("ajustes", "tiene que ser texto");
    if (tipo == "choice" && !d->opciones.empty()) {
        for (const auto& [v, rotulo] : d->opciones)
            if (valor.get<std::string>() == v) return {};
        return ba::i18n::traducir("ajustes", "no es una de las opciones");
    }
    return {};
}

